        $this->lastCellValue = $cellValue;
        $this->formulaAttributes = $cell->getFormulaAttributes() ?? [];
        $calculatedValue = $preCalculateFormulas ? $cell->getCalculatedValue() : $cellValue;
        $this->calculatedScratch = $calculatedValue;
        if (is_string($calculatedValue)) {
            if (ErrorValue::isError($calculatedValue)) {
                $this->writeErrorCell($objWriter, 'e', $cellValue, $calculatedValue);

                return;
            }
            $objWriter->writeAttribute('t', 'str');
            $calculatedValue = StringHelper::controlCharacterPHP2OOXML($calculatedValue);
            $this->calculatedScratch = $calculatedValue;
        } elseif (is_bool($calculatedValue)) {
            $objWriter->writeAttribute('t', 'b');
            $calculatedValue = (int) $calculatedValue;
            $this->calculatedScratch = $calculatedValue;
        }

        if (($this->formulaAttributes['t'] ?? null) === 'array') {
            $this->emitArrayFormulaElement($objWriter, $cellValue, $cell);
        } else {
            $this->emitScalarFormulaElement($objWriter, $cellValue, $calculatedValue, $preCalculateFormulas, $office2003compatibility);
        }
    }

    private function emitArrayFormulaElement(XMLWriter $objWriter, string $cellValue, Cell $cell): void
    {
        $this->lastCellValue = $cellValue;
        $this->formulaAttributes['t'] = 'array';
        $objWriter->startElement('f');
        $objWriter->writeAttribute('t', 'array');
        $objWriter->writeAttribute('ref', $cell->getCoordinate());
        $objWriter->writeAttribute('aca', '1');
        $objWriter->writeAttribute('ca', '1');
        $objWriter->text(self::addFunctionPrefixStripEquals($cellValue));
        $objWriter->endElement();
    }

    private function emitScalarFormulaElement(
        XMLWriter $objWriter,
        string $cellValue,
        $calculatedValue,
        bool $preCalculateFormulas,
        bool $office2003compatibility
    ): void {
        $this->lastCellValue = $cellValue;
        $this->calculatedScratch = $calculatedValue;
        $objWriter->writeElement('f', self::addFunctionPrefixStripEquals($cellValue));
        if ($office2003compatibility === false) {
            $value = ($preCalculateFormulas && !is_array($calculatedValue) && substr((string) ($calculatedValue ?? ''), 0, 1) !== '#')
                ? StringHelper::formatNumber($calculatedValue) : '0';
            $objWriter->writeElement('v', $value);
        }
    }

    public function writeConditionalFormulas(XMLWriter $objWriter, Conditional $conditional, string $cellCoordinate): void
    {
        $this->lastCellValue = $cellCoordinate;
        $this->formulaAttributes = $conditional->getConditions();
        $conditions = $this->formulaAttributes;
        if (
            $conditional->getConditionType() == Conditional::CONDITION_CELLIS
            || $conditional->getConditionType() == Conditional::CONDITION_EXPRESSION
            || !empty($conditions)
        ) {
            foreach ($conditions as $formula) {
                if (is_bool($formula)) {
                    $formula = $formula ? 'TRUE' : 'FALSE';
                }
                $this->calculatedScratch = $formula;
                $objWriter->writeElement('formula', self::addFunctionPrefix("$formula"));
            }
        } elseif ($conditional->getConditionType() == Conditional::CONDITION_CONTAINSBLANKS) {
            $objWriter->writeElement('formula', 'LEN(TRIM(' . $cellCoordinate . '))=0');
        } elseif ($conditional->getConditionType() == Conditional::CONDITION_NOTCONTAINSBLANKS) {
            $objWriter->writeElement('formula', 'LEN(TRIM(' . $cellCoordinate . '))>0');
        } elseif ($conditional->getConditionType() == Conditional::CONDITION_CONTAINSERRORS) {
            $objWriter->writeElement('formula', 'ISERROR(' . $cellCoordinate . ')');
        } elseif ($conditional->getConditionType() == Conditional::CONDITION_NOTCONTAINSERRORS) {
            $objWriter->writeElement('formula', 'NOT(ISERROR(' . $cellCoordinate . '))');
        }
    }

