            $objWriter->writeAttribute('timePeriod', $txt);
            if (empty($conditional->getConditions())) {
                $operator = $conditional->getOperatorType();
                $this->formulaAttributes = ['operator' => $operator];
                if ($operator == Conditional::TIMEPERIOD_TODAY) {
                    $objWriter->writeElement('formula', 'FLOOR(' . $cellCoordinate . ')=TODAY()');
                } elseif ($operator == Conditional::TIMEPERIOD_TOMORROW) {
                    $objWriter->writeElement('formula', 'FLOOR(' . $cellCoordinate . ')=TODAY()+1');
                } elseif ($operator == Conditional::TIMEPERIOD_YESTERDAY) {
